package com.quoth;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.EnumMap;
import java.util.List;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Random;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.util.Filepath;

/**
 * Plays Quoth's own voices, and any sound files the player has added, through RuneLite's
 * AudioPlayer, off the client thread. Each blip is decoded once, then pitched and trimmed in
 * memory and handed over as a small WAV. Unlike game sounds these can be pitched and shortened,
 * but they do not follow the in-game sound effect volume, hence their own.
 */
@Slf4j
final class BlipPlayer
{
	private static final int FADE_OUT_MS = 5;
	// A voice blip is a fraction of a second; anything longer is cut on load so a stray song in
	// the folder cannot eat memory. Blips are trimmed further as they play.
	private static final int MAX_SAMPLE_MS = 2000;
	private static final long MAX_FILE_BYTES = 20L * 1024 * 1024;

	private final Map<BlipSound, byte[]> bundled = new EnumMap<>(BlipSound.class);
	private final Random random = new Random();
	private final Filepath userDir;
	private final AudioPlayer audio;
	private volatile Map<String, byte[]> user = new LinkedHashMap<>();
	private long userDirStamp = Long.MIN_VALUE;
	private ExecutorService executor;

	/** @param userDir the player's sound file folder; null when the client could not provide one */
	BlipPlayer(Filepath userDir, AudioPlayer audio)
	{
		this.userDir = userDir;
		this.audio = audio;
	}

	void start()
	{
		for (BlipSound b : BlipSound.values())
		{
			if (!b.isBundled())
			{
				continue;
			}
			try (InputStream in = BlipPlayer.class.getResourceAsStream("blips/" + b.getSample() + ".wav"))
			{
				bundled.put(b, Wav.decode(in.readAllBytes()));
			}
			catch (Exception e)
			{
				log.warn("Quoth: could not load blip {}", b, e);
			}
		}
		// The samples folder is optional and never created: only read if the player made it.
		executor = Executors.newSingleThreadExecutor(r ->
		{
			Thread t = new Thread(r, "quoth-blips");
			t.setDaemon(true);
			return t;
		});
	}

	void stop()
	{
		if (executor != null)
		{
			executor.shutdownNow();
			executor = null;
		}
	}

	/** Whether the folder holds a sample with this name (no extension), rescanning if it changed. */
	boolean hasUser(String name)
	{
		refreshUser();
		for (String key : user.keySet())
		{
			if (key.equalsIgnoreCase(name))
			{
				return true;
			}
		}
		return false;
	}

	/** Rescans the samples folder if it changed and returns how many samples loaded. */
	synchronized int refreshUser()
	{
		long stamp = lastModified(userDir);
		if (stamp == userDirStamp)
		{
			return user.size();
		}
		userDirStamp = stamp;
		Map<String, byte[]> loaded = new LinkedHashMap<>();
		for (Filepath f : listFiles(userDir))
		{
			String name = f.getFileName();
			if (!f.isFile() || !name.toLowerCase(Locale.ROOT).endsWith(".wav"))
			{
				continue;
			}
			try (InputStream in = f.openInputStream())
			{
				if (f.size() > MAX_FILE_BYTES)
				{
					continue;
				}
				byte[] pcm = Wav.decode(in.readAllBytes());
				loaded.put(stripExtension(name), Resample.trim(pcm, Wav.RATE * MAX_SAMPLE_MS / 1000, 0));
			}
			catch (Exception e)
			{
				log.warn("Quoth: skipped sample {}: {}", name, e.getMessage());
			}
		}
		user = loaded;
		return loaded.size();
	}

	/** Milliseconds, or 0 when there is no folder, which matches File.lastModified. */
	private static long lastModified(Filepath dir)
	{
		if (dir == null || !dir.isDirectory())
		{
			return 0;
		}
		try
		{
			return dir.getLastModifiedTime().toMillis();
		}
		catch (IOException e)
		{
			return 0;
		}
	}

	/** The folder's direct children in name order; empty when there is no folder. */
	private static List<Filepath> listFiles(Filepath dir)
	{
		if (dir == null || !dir.isDirectory())
		{
			return List.of();
		}
		try (Stream<Filepath> s = dir.walk(1))
		{
			return s.filter(f -> !f.equals(dir)).sorted().collect(Collectors.toList());
		}
		catch (IOException e)
		{
			log.warn("Quoth: could not list sound files: {}", e.getMessage());
			return List.of();
		}
	}

	/**
	 * @param sampleName a sample in the folder to play, by name without extension; null plays
	 *                   the bundled voice
	 * @param semitones fixed pitch offset
	 * @param variationCents random spread either side, per blip
	 * @param volume 0-100
	 * @param lengthMs cut each blip to this long after pitching; 0 plays it whole
	 */
	void play(BlipSound voice, String sampleName, int semitones, int variationCents, int volume, int lengthMs)
	{
		ExecutorService ex = executor;
		if (ex == null || volume <= 0)
		{
			return;
		}
		double cents = variationCents <= 0 ? 0 : (random.nextDouble() * 2 - 1) * variationCents;
		double ratio = Resample.ratio(semitones, cents);
		int maxFrames = lengthMs <= 0 ? 0 : Wav.RATE * lengthMs / 1000;
		int fadeFrames = Wav.RATE * FADE_OUT_MS / 1000;
		float gainDb = gainDb(volume);
		ex.execute(() ->
		{
			byte[] data = sampleName != null ? pickUser(sampleName) : bundled.get(voice);
			if (data == null)
			{
				return;
			}
			byte[] wav = Wav.encode(Resample.trim(Resample.shift(data, ratio), maxFrames, fadeFrames));
			try
			{
				audio.play(new ByteArrayInputStream(wav), gainDb);
			}
			catch (Exception e)
			{
				log.debug("Quoth: blip failed", e);
			}
		});
	}

	/** 0-100 volume as decibels of gain; 100 is unity. */
	static float gainDb(int volume)
	{
		return (float) (20 * Math.log10(Math.max(1, Math.min(100, volume)) / 100.0));
	}

	private byte[] pickUser(String name)
	{
		refreshUser();
		for (Map.Entry<String, byte[]> e : user.entrySet())
		{
			if (e.getKey().equalsIgnoreCase(name))
			{
				return e.getValue();
			}
		}
		return null;
	}

	private static String stripExtension(String name)
	{
		int dot = name.lastIndexOf('.');
		return dot > 0 ? name.substring(0, dot) : name;
	}
}

package com.quoth;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum BlipSound
{
	OFF("Off", null, -1, 0),
	SOFT("Soft", "soft", -1, 0),
	WARM("Warm", "warm", -1, 0),
	SOFTER("Softer", "soft", -1, -7),
	REED("Reed", "reed", -1, 0),
	BELL("Bell", "bell", -1, 0),
	PIP("Pip", "pip", -1, 0),
	WOOD("Wood", "wood", -1, 0),
	// Game sounds by ID, ascending, picked by ear. Each plays from a matching stab file in
	// .runelite/quoth when there is one (so pitch, volume and mood apply), else from the game.
	SOUND_1833("Game 1833", null, 1833, 0),
	SOUND_2215("Game 2215", null, 2215, 0),
	BOOP("Game 2266", null, 2266, 0),
	SOUND_2269("Game 2269", null, 2269, 0),
	SOUND_2278("Game 2278", null, 2278, 0),
	SOUND_5242("Game 5242", null, 5242, 0),
	SOUND_7013("Game 7013", null, 7013, 0),
	CUSTOM("Game (Custom ID)", null, -1, 0);

	private static final BlipSound[] GAME_PRESETS = {
		SOUND_1833, SOUND_2215, BOOP, SOUND_2269, SOUND_2278, SOUND_5242, SOUND_7013
	};

	private final String label;
	/** Bundled sample name, or null for game sounds. */
	private final String sample;
	/** Game sound ID for presets, or -1. */
	private final int id;
	/** Semitones built into this voice, on top of the Pitch setting. Needs a file to apply. */
	private final int pitch;

	boolean isBundled()
	{
		return sample != null;
	}

	/** Played by Quoth itself from a bundled file, so pitch, volume and mood always apply. */
	boolean isOwnAudio()
	{
		return isBundled();
	}

	boolean isGamePreset()
	{
		return id >= 0;
	}

	/** The game preset with this ID, or {@code null}. */
	static BlipSound presetFor(int id)
	{
		for (BlipSound b : GAME_PRESETS)
		{
			if (b.id == id)
			{
				return b;
			}
		}
		return null;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.quoth;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(QuothConfig.GROUP)
public interface QuothConfig extends Config
{
	String GROUP = "quoth";

	@ConfigSection(name = "Text", description = "How dialogue appears", position = 0)
	String textSection = "text";

	@ConfigSection(name = "Voice", description = "The sound of each word", position = 1)
	String voiceSection = "voice";

	@ConfigSection(name = "Explore", description = "Audition the game's own sounds", position = 2)
	String exploreSection = "explore";

	@ConfigItem(
		keyName = "mode",
		name = "Reveal by",
		description = "Word or letter at a time, or Fade: each word fades in over the ones before it",
		section = textSection,
		position = 0
	)
	default RevealMode mode()
	{
		return RevealMode.WORD;
	}

	@Range(min = 40, max = 600)
	@Units(Units.MILLISECONDS)
	@ConfigItem(
		keyName = "pace",
		name = "Pace",
		description = "Time per word. Letters and fades follow it: at 130 ms a letter takes 70 ms and a fade 390 ms",
		section = textSection,
		position = 1
	)
	default int pace()
	{
		return 130;
	}

	@ConfigItem(
		keyName = "clickToFinish",
		name = "Click to finish",
		description = "While a line is appearing, the first click on continue (or Space) shows the rest; the next continues",
		section = textSection,
		position = 2
	)
	default boolean clickToFinish()
	{
		return true;
	}

	// New key: "blip" stored values like RANDOM no longer exist in this list.
	@ConfigItem(
		keyName = "voice",
		name = "Voice",
		description = "Quoth's own voices (Soft to Wood) take every setting. Game voices play the game's own sound, so Pitch, Volume, speaker voices and mood only reach them if you have a matching file in .runelite/quoth",
		section = voiceSection,
		position = 0
	)
	default BlipSound voice()
	{
		// Bundled, so per-speaker pitch and punctuation mood work on every machine.
		return BlipSound.SOFT;
	}

	@Range(min = -12, max = 12)
	@ConfigItem(
		keyName = "pitch",
		name = "Pitch",
		description = "Semitones up or down, for Quoth's own voices",
		section = voiceSection,
		position = 1
	)
	default int pitch()
	{
		return 0;
	}



	@ConfigItem(
		keyName = "speakerPitch",
		name = "Voice per speaker",
		description = "Each NPC gets a pitch of their own from their name; barbarians, ogres and dwarves sound lower, gnomes and fairies higher. Quoth's own voices",
		section = voiceSection,
		position = 2
	)
	default boolean speakerPitch()
	{
		return true;
	}

	@Range(min = 0, max = 100)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "volume",
		name = "Volume",
		description = "For Quoth's own voices; game voices follow the in-game sound effects volume",
		section = voiceSection,
		position = 3
	)
	default int volume()
	{
		return 60;
	}

	@ConfigItem(
		keyName = "soundId",
		name = "Custom sound ID",
		description = "Game sound effect ID. Follows the game preset you pick; editing it switches Voice to that preset or Custom",
		section = exploreSection,
		position = 0
	)
	default int soundId()
	{
		return 2266;
	}

	@ConfigItem(
		keyName = "rollKey",
		name = "Roll random sound",
		description = "Press to hear a random game sound. It becomes your Custom sound ID and its number is shown in chat",
		section = exploreSection,
		position = 1
	)
	default Keybind rollKey()
	{
		return Keybind.NOT_SET;
	}
}

package com.quoth;

import com.google.inject.Provides;
import java.awt.event.KeyEvent;
import java.io.IOException;
import java.util.Random;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PluginChanged;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.HotkeyListener;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Quoth",
	description = "Dialogue types itself out in the chatbox, word by word, with an optional voice blip",
	tags = {"dialogue", "typewriter", "chatbox", "rpg", "text", "immersion", "sound"},
	internalName = "quoth",
	// Sound files used to live in .runelite/quoth; the client moves that folder over once.
	legacyDataDirectory = "quoth"
)
public class QuothPlugin extends Plugin
{
	// NPC speaking, player speaking, plain message box.
	private static final int[] DIALOGUE_TEXT = {
		InterfaceID.ChatLeft.TEXT,
		InterfaceID.ChatRight.TEXT,
		InterfaceID.Messagebox.TEXT,
	};

	// A blip per letter sounds like a drill; one per this many letters reads as speech.
	private static final int LETTERS_PER_BLIP = 3;


	// Fixed character for Quoth's own audio, so the settings stay few: a little random pitch
	// keeps a voice alive, and a cap keeps every sample a short stab.
	private static final int VARIATION_CENTS = 30;
	private static final int STAB_MS = 150;
	private static final int QUESTION_LIFT = 3;
	private static final double EXCLAIM_GAIN = 1.5;

	private static final int[] DIALOGUE_CONTINUE = {
		InterfaceID.ChatLeft.CONTINUE,
		InterfaceID.ChatRight.CONTINUE,
		InterfaceID.Messagebox.CONTINUE,
	};

	private static final String IMMERSIVE_DIALOGUE = "ImmersiveDialoguePlugin";
	private static final String IMMERSIVE_GROUP = "immersivedialogue";
	private static final int IMMERSIVE_DEFAULT_SPEED = 35;

	// Size of the game's synth list: symbols/synth.sym in Joshua-F/osrs-dumps, 2026-09-27.
	private static final int SYNTH_COUNT = 12155;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private QuothConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private PluginManager pluginManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	private final Random random = new Random();
	@Inject
	private AudioPlayer audioPlayer;

	// Built in startUp, once the AudioPlayer has been injected.
	private BlipPlayer player;
	private boolean immersiveActive;
	private String voicedLine;
	private long voicedStart;
	private int voicedChars;
	private Reveal voicedReveal;
	private int voicedShown;
	private int speakerPitch;
	private int inkFrom;
	private int inkTo;

	private final HotkeyListener rollListener = new HotkeyListener(() -> config.rollKey())
	{
		@Override
		public void hotkeyPressed()
		{
			clientThread.invoke(QuothPlugin.this::roll);
		}
	};

	// The game's own text widget is never edited: other plugins (overhead text, dialogue
	// loggers) read it every tick and would see each partial line as a new one. Instead the
	// original is hidden with its full text intact and the reveal is drawn in a copy on top.
	private Widget source;
	private Widget copy;
	private String fullText;
	private Reveal reveal;
	private RevealMode mode;
	private long startNanos;
	private int shown;
	private boolean done;
	/** Read from the key thread, so volatile: true while a line is still appearing. */
	private volatile boolean revealing;

	private final KeyListener spaceToFinish = new KeyListener()
	{
		@Override
		public void keyTyped(KeyEvent e)
		{
		}

		@Override
		public void keyPressed(KeyEvent e)
		{
			if (e.getKeyCode() == KeyEvent.VK_SPACE && revealing && config.clickToFinish())
			{
				e.consume();
				clientThread.invoke(QuothPlugin.this::finishLine);
			}
		}

		@Override
		public void keyReleased(KeyEvent e)
		{
		}
	};

	@Provides
	QuothConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(QuothConfig.class);
	}

	@Override
	protected void startUp()
	{
		Filepath samples = null;
		try
		{
			samples = getPluginDirectory();
		}
		catch (IOException e)
		{
			log.warn("Quoth: sound file folder unavailable, bundled voices only", e);
		}
		player = new BlipPlayer(samples, audioPlayer);
		player.start();
		keyManager.registerKeyListener(rollListener);
		keyManager.registerKeyListener(spaceToFinish);
		immersiveActive = isImmersiveActive();
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(rollListener);
		keyManager.unregisterKeyListener(spaceToFinish);
		player.stop();
		clientThread.invoke(this::release);
	}

	/**
	 * Immersive Dialogue rebuilds the chatbox every frame and has its own typing and voice
	 * blips, so running both would fight over the same widgets and double every sound.
	 */
	@Subscribe
	public void onPluginChanged(PluginChanged event)
	{
		immersiveActive = isImmersiveActive();
	}

	private boolean isImmersiveActive()
	{
		for (Plugin p : pluginManager.getPlugins())
		{
			if (IMMERSIVE_DIALOGUE.equals(p.getClass().getSimpleName()) && pluginManager.isPluginActive(p))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * With Immersive Dialogue drawing the text, Quoth only lends its voice: it runs blips on
	 * Immersive's own clock (Text speed, characters per second) and never touches its panel.
	 * Immersive only types while its Voice blips setting is on; set its Voice volume to 0 so
	 * one voice speaks, not two.
	 * ponytail: clicking to skip a line in Immersive is invisible here, so blips run to the
	 * end of that line; mirror its skip if that ever grates.
	 */
	private void voiceImmersive()
	{
		boolean typing = Boolean.TRUE.equals(configManager.getConfiguration(IMMERSIVE_GROUP, "voiceBlips", Boolean.class));
		String body = null;
		int speakerId = -1;
		for (int id : DIALOGUE_TEXT)
		{
			Widget w = client.getWidget(id);
			// Immersive hides the native widgets but leaves their text intact.
			if (w != null && w.getText() != null && !w.getText().isEmpty())
			{
				body = Text.removeTags(w.getText().replace("<br>", " "));
				speakerId = id;
				break;
			}
		}
		if (body == null)
		{
			voicedLine = null;
			return;
		}
		if (!body.equals(voicedLine))
		{
			voicedLine = body;
			voicedStart = System.nanoTime();
			voicedChars = 0;
			voicedShown = 0;
			voicedReveal = Reveal.of(body, config.mode());
			speakerPitch = speakerPitchFor(speakerId);
			log.debug("Quoth: voicing Immersive line, {} steps, Immersive typing={}", voicedReveal.size(), typing);
		}
		if (!typing)
		{
			// Immersive shows the line whole; Quoth still speaks it, on its own rhythm.
			long elapsedMs = (System.nanoTime() - voicedStart) / 1_000_000L;
			int target = voicedReveal.startedBy(elapsedMs, Math.max(1, voicedDelay()));
			int mood = target > voicedShown ? voicedReveal.mood(target - 1) : 0;
			boolean blip = target > voicedShown && (config.mode() != RevealMode.LETTER
				|| voicedShown / LETTERS_PER_BLIP != target / LETTERS_PER_BLIP || voicedShown == 0 || mood != 0);
			voicedShown = Math.max(voicedShown, target);
			if (blip && config.voice() != BlipSound.OFF)
			{
				playBlip(config.voice(), mood);
			}
			return;
		}

		Integer speed = configManager.getConfiguration(IMMERSIVE_GROUP, "textSpeed", Integer.class);
		double cps = speed != null && speed > 0 ? speed : IMMERSIVE_DEFAULT_SPEED;
		long elapsedMs = (System.nanoTime() - voicedStart) / 1_000_000L;
		int target = (int) Math.min(body.length(), elapsedMs * cps / 1000.0);
		boolean blip = false;
		for (int i = voicedChars; i < target; i++)
		{
			char c = body.charAt(i);
			if (Character.isWhitespace(c))
			{
				continue;
			}
			boolean wordStart = i == 0 || Character.isWhitespace(body.charAt(i - 1));
			blip |= config.mode() != RevealMode.LETTER ? wordStart : nonSpaceIndex(body, i) % LETTERS_PER_BLIP == 0;
		}
		voicedChars = target;
		BlipSound voice = config.voice();
		if (blip && voice != BlipSound.OFF)
		{
			playBlip(voice);
		}
	}

	private int voicedDelay()
	{
		return config.mode().delay(config.pace());
	}

	/** An NPC speaking gets a pitch from their name; the player and message boxes stay central. */
	private int speakerPitchFor(int textWidgetId)
	{
		if (textWidgetId != InterfaceID.ChatLeft.TEXT)
		{
			return 0;
		}
		Widget name = client.getWidget(InterfaceID.ChatLeft.NAME);
		return Speaker.pitchFor(name == null ? null : name.getText());
	}

	private static int nonSpaceIndex(String s, int i)
	{
		int n = 0;
		for (int k = 0; k < i; k++)
		{
			if (!Character.isWhitespace(s.charAt(k)))
			{
				n++;
			}
		}
		return n;
	}

	private void roll()
	{
		int id = random.nextInt(SYNTH_COUNT);
		// The sync handler moves Voice to the matching preset or Custom.
		configManager.setConfiguration(QuothConfig.GROUP, "soundId", id);
		client.playSoundEffect(id);
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage("Quoth: sound " + id + " (now your Custom sound ID)")
			.build());
	}

	@Subscribe
	public void onClientTick(ClientTick tick)
	{
		if (immersiveActive)
		{
			release();
			voiceImmersive();
			return;
		}

		Widget widget = null;
		for (int id : DIALOGUE_TEXT)
		{
			Widget w = client.getWidget(id);
			// The one we hid is still the live one; any other must be visible to count.
			if (w != null && (w == source || !w.isHidden()))
			{
				widget = w;
				break;
			}
		}

		if (widget == null)
		{
			// Dialogue closed. Forget it, so an identical next line still animates.
			release();
			return;
		}

		String current = widget.getText();
		if (current == null)
		{
			return;
		}

		// ponytail: a new line is detected by its text changing. Two identical lines in a row
		// on the same widget without the box closing will not re-animate; hook WidgetLoaded if that shows up.
		if (widget != source || !current.equals(fullText))
		{
			release();
			start(widget, current);
		}

		advance();
	}

	private void start(Widget widget, String text)
	{
		source = widget;
		fullText = text;
		mode = config.mode();
		reveal = Reveal.of(text, mode);
		startNanos = System.nanoTime();
		shown = 0;
		done = false;
		speakerPitch = speakerPitchFor(widget.getId());
		inkTo = widget.getTextColor() & 0xffffff;
		inkFrom = Speaker.faintOf(inkTo);
		if (reveal.size() == 0)
		{
			return;
		}

		copy = widget.getParent().createChild(-1, WidgetType.TEXT);
		copy.setFontId(widget.getFontId());
		copy.setTextColor(widget.getTextColor());
		copy.setTextShadowed(widget.getTextShadowed());
		copy.setXTextAlignment(widget.getXTextAlignment());
		copy.setYTextAlignment(widget.getYTextAlignment());
		copy.setLineHeight(widget.getLineHeight());
		copy.setXPositionMode(widget.getXPositionMode());
		copy.setYPositionMode(widget.getYPositionMode());
		copy.setWidthMode(widget.getWidthMode());
		copy.setHeightMode(widget.getHeightMode());
		copy.setOriginalX(widget.getOriginalX());
		copy.setOriginalY(widget.getOriginalY());
		copy.setOriginalWidth(widget.getOriginalWidth());
		copy.setOriginalHeight(widget.getOriginalHeight());
		copy.setText("");
		copy.revalidate();
		widget.setHidden(true);
	}

	private void advance()
	{
		if (copy == null || done)
		{
			return;
		}
		if (!source.isHidden())
		{
			// The game re-showed its widget mid-line; keep it out of the way.
			source.setHidden(true);
		}

		long elapsedMs = (System.nanoTime() - startNanos) / 1_000_000L;
		int delay = Math.max(1, delay());
		int fadeMs = RevealMode.fadeLength(config.pace());
		int target = reveal.startedBy(elapsedMs, delay);
		boolean stepped = target > shown;

		BlipSound voice = config.voice();
		int mood = stepped ? reveal.mood(target - 1) : 0;
		boolean blip = stepped && voice != BlipSound.OFF && (mode != RevealMode.LETTER
			|| shown / LETTERS_PER_BLIP != target / LETTERS_PER_BLIP
			|| shown == 0 || mood != 0);
		shown = Math.max(shown, target);

		boolean finished = mode == RevealMode.FADE
			? elapsedMs >= reveal.inkedBy(delay, fadeMs)
			: shown >= reveal.size();
		if (finished)
		{
			finishLine();
		}
		else if (mode == RevealMode.FADE)
		{
			copy.setText(reveal.inked(elapsedMs, delay, fadeMs, inkFrom, inkTo));
		}
		else if (stepped)
		{
			copy.setText(reveal.prefix(shown));
		}
		if (blip)
		{
			playBlip(voice, mood);
		}
		revealing = !done;
	}

	/** Shows the rest of the line at once and hands the box back to the game's own widget. */
	private void finishLine()
	{
		if (copy == null || done)
		{
			return;
		}
		done = true;
		revealing = false;
		shown = reveal.size();
		source.setHidden(false);
		copy.setHidden(true);
	}

	/**
	 * While a line is appearing, the first click on continue finishes it instead of moving on,
	 * so no line is skipped half-read. The click after that continues as normal.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!revealing || !config.clickToFinish())
		{
			return;
		}
		for (int id : DIALOGUE_CONTINUE)
		{
			if (event.getParam1() == id)
			{
				event.consume();
				finishLine();
				return;
			}
		}
	}

	private void playBlip(BlipSound voice)
	{
		playBlip(voice, 0);
	}

	private void playBlip(BlipSound voice, int mood)
	{
		String sample = null;
		if (!voice.isOwnAudio())
		{
			int id = voice == BlipSound.CUSTOM ? config.soundId() : voice.getId();
			if (!player.hasUser(String.valueOf(id)))
			{
				// No stab file for this ID: the game plays it, unpitched, at the game's volume.
				client.playSoundEffect(id);
				return;
			}
			sample = String.valueOf(id);
		}
		{
			int pitch = config.pitch() + voice.getPitch() + (config.speakerPitch() ? speakerPitch : 0);
			int volume = config.volume();
			if ((mood & Reveal.MOOD_QUESTION) != 0)
			{
				pitch += QUESTION_LIFT;
			}
			if ((mood & Reveal.MOOD_EXCLAIM) != 0)
			{
				volume = (int) Math.min(100, Math.round(volume * EXCLAIM_GAIN));
			}
			player.play(voice, sample, pitch, VARIATION_CENTS, volume, STAB_MS);
		}
	}

	private int delay()
	{
		return mode.delay(config.pace());
	}

	/**
	 * Keeps the dropdown and the ID field telling the same story: picking a preset writes its
	 * ID into the field, and typing an ID selects the matching preset, or Custom if none.
	 * Each write is skipped when the other side already agrees, so neither echo loops.
	 * ponytail: RuneLite's settings panel only redraws when reopened, so the field shows the
	 * synced value after closing and reopening Quoth's settings.
	 */
	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!QuothConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		BlipSound voice = config.voice();
		int id = config.soundId();
		if ("voice".equals(event.getKey()))
		{
			if (voice.isGamePreset() && id != voice.getId())
			{
				configManager.setConfiguration(QuothConfig.GROUP, "soundId", voice.getId());
			}
		}
		else if ("soundId".equals(event.getKey()))
		{
			if (voice == BlipSound.CUSTOM || (voice.isGamePreset() && id == voice.getId()))
			{
				return;
			}
			BlipSound match = BlipSound.presetFor(id);
			configManager.setConfiguration(QuothConfig.GROUP, "voice", match != null ? match : BlipSound.CUSTOM);
		}
	}

	/** Restores the game's widget and drops the copy. Safe to call at any time. */
	private void release()
	{
		revealing = false;
		if (copy != null)
		{
			copy.setHidden(true);
			if (source != null)
			{
				source.setHidden(false);
			}
		}
		source = null;
		copy = null;
		fullText = null;
	}
}

package com.quoth;

/** Pitch shifting by resampling 16-bit mono PCM: higher pitch plays shorter, like tape. */
final class Resample
{
	private Resample()
	{
	}

	/** Pitch ratio for a shift in semitones plus cents. */
	static double ratio(double semitones, double cents)
	{
		return Math.pow(2, (semitones + cents / 100.0) / 12.0);
	}

	/**
	 * Resamples little-endian signed 16-bit mono PCM by {@code ratio} with linear interpolation.
	 * A ratio of 2 is an octave up at half the length.
	 */
	static byte[] shift(byte[] pcm, double ratio)
	{
		int inFrames = pcm.length / 2;
		int outFrames = Math.max(1, (int) (inFrames / ratio));
		byte[] out = new byte[outFrames * 2];
		for (int i = 0; i < outFrames; i++)
		{
			double pos = i * ratio;
			int a = (int) pos;
			int b = Math.min(a + 1, inFrames - 1);
			double frac = pos - a;
			int s = (int) Math.round(sample(pcm, Math.min(a, inFrames - 1)) * (1 - frac) + sample(pcm, b) * frac);
			out[2 * i] = (byte) s;
			out[2 * i + 1] = (byte) (s >> 8);
		}
		return out;
	}

	/**
	 * Cuts 16-bit mono PCM to at most {@code maxFrames}, ramping the last {@code fadeFrames}
	 * down to silence so the cut does not click. Shorter input is returned unchanged.
	 */
	static byte[] trim(byte[] pcm, int maxFrames, int fadeFrames)
	{
		int frames = pcm.length / 2;
		if (maxFrames <= 0 || maxFrames >= frames)
		{
			return pcm;
		}
		byte[] out = java.util.Arrays.copyOf(pcm, maxFrames * 2);
		int fade = Math.min(fadeFrames, maxFrames);
		for (int i = 0; i < fade; i++)
		{
			int frame = maxFrames - fade + i;
			double gain = 1 - (i + 1) / (double) fade;
			int s = (int) Math.round(sample(out, frame) * gain);
			out[2 * frame] = (byte) s;
			out[2 * frame + 1] = (byte) (s >> 8);
		}
		return out;
	}

	private static int sample(byte[] pcm, int frame)
	{
		return (short) ((pcm[2 * frame] & 0xff) | (pcm[2 * frame + 1] << 8));
	}
}

package com.quoth;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Splits dialogue text into reveal steps and schedules them like speech. Game markup
 * ({@code <col=ff0000>}, {@code <br>}) is never split: tags and whitespace ride along with the
 * next visible unit, so every prefix is well-formed text the chatbox can render. Punctuation
 * holds the next step back, so a line breathes at commas and stops at full stops.
 */
final class Reveal
{
	// Extra delays after a step ending in each kind of punctuation.
	static final int PAUSE_COMMA = 1;
	static final int PAUSE_STOP = 3;
	static final int PAUSE_ELLIPSIS = 5;

	private final List<String> steps;
	/** When each step starts, in units of one delay. */
	private final int[] startUnits;

	private Reveal(List<String> steps)
	{
		this.steps = steps;
		startUnits = new int[steps.size()];
		String[] visible = new String[steps.size()];
		for (int k = 0; k < steps.size(); k++)
		{
			visible[k] = steps.get(k).replaceAll("<[^>]*>", "");
		}
		StringBuilder soFar = new StringBuilder();
		int units = 0;
		for (int k = 0; k < steps.size(); k++)
		{
			startUnits[k] = units;
			soFar.append(visible[k]);
			char next = k + 1 < steps.size() ? firstNonSpace(visible[k + 1]) : ' ';
			units += 1 + pauseAfter(soFar, next);
		}
	}

	static Reveal of(String text, RevealMode mode)
	{
		List<String> steps = new ArrayList<>();
		StringBuilder pending = new StringBuilder();
		int i = 0;
		while (i < text.length())
		{
			char c = text.charAt(i);
			if (c == '<')
			{
				int end = text.indexOf('>', i);
				if (end < 0)
				{
					end = text.length() - 1;
				}
				pending.append(text, i, end + 1);
				i = end + 1;
			}
			else if (Character.isWhitespace(c))
			{
				pending.append(c);
				i++;
			}
			else
			{
				int end = i;
				while (end < text.length() && text.charAt(end) != '<' && !Character.isWhitespace(text.charAt(end)))
				{
					end++;
				}
				if (mode != RevealMode.LETTER)
				{
					steps.add(pending + text.substring(i, end));
					pending.setLength(0);
				}
				else
				{
					for (int k = i; k < end; k++)
					{
						steps.add(pending.toString() + text.charAt(k));
						pending.setLength(0);
					}
				}
				i = end;
			}
		}
		if (pending.length() > 0)
		{
			if (steps.isEmpty())
			{
				steps.add(pending.toString());
			}
			else
			{
				int last = steps.size() - 1;
				steps.set(last, steps.get(last) + pending);
			}
		}
		return new Reveal(Collections.unmodifiableList(steps));
	}

	/**
	 * Extra delays after the text so far, given the next visible character. Runs of punctuation
	 * ("?!", "...") pause once, at their end, so letter and word modes breathe alike.
	 */
	static int pauseAfter(CharSequence soFar, char next)
	{
		String t = soFar.toString().trim();
		while (!t.isEmpty() && "\"')]".indexOf(t.charAt(t.length() - 1)) >= 0)
		{
			t = t.substring(0, t.length() - 1);
		}
		if (t.isEmpty() || ".!?,;:\u2026".indexOf(next) >= 0)
		{
			return 0;
		}
		if (t.endsWith("...") || t.endsWith("\u2026"))
		{
			return PAUSE_ELLIPSIS;
		}
		switch (t.charAt(t.length() - 1))
		{
			case '.':
			case '!':
			case '?':
				return PAUSE_STOP;
			case ',':
			case ';':
			case ':':
				return PAUSE_COMMA;
			default:
				return 0;
		}
	}

	private static char firstNonSpace(String s)
	{
		for (int i = 0; i < s.length(); i++)
		{
			if (!Character.isWhitespace(s.charAt(i)))
			{
				return s.charAt(i);
			}
		}
		return ' ';
	}

	static final int MOOD_QUESTION = 1;
	static final int MOOD_EXCLAIM = 2;

	/** How a step should sound: lifted if it ends a question, louder if it ends an exclamation. */
	int mood(int step)
	{
		if (step < 0 || step >= steps.size())
		{
			return 0;
		}
		String t = steps.get(step).replaceAll("<[^>]*>", "").trim();
		while (!t.isEmpty() && "\"')".indexOf(t.charAt(t.length() - 1)) >= 0)
		{
			t = t.substring(0, t.length() - 1);
		}
		int mood = 0;
		for (int i = t.length() - 1; i >= 0 && "?!".indexOf(t.charAt(i)) >= 0; i--)
		{
			mood |= t.charAt(i) == '?' ? MOOD_QUESTION : MOOD_EXCLAIM;
		}
		return mood;
	}

	int size()
	{
		return steps.size();
	}

	long startMs(int step, int delayMs)
	{
		return (long) startUnits[step] * delayMs;
	}

	/** How many steps have started by {@code elapsedMs}. */
	int startedBy(long elapsedMs, int delayMs)
	{
		int n = 0;
		while (n < steps.size() && startMs(n, delayMs) <= elapsedMs)
		{
			n++;
		}
		return n;
	}

	/** Text with the first {@code count} steps shown; {@code count >= size()} is the full text. */
	String prefix(int count)
	{
		StringBuilder sb = new StringBuilder();
		for (int k = 0; k < Math.min(count, steps.size()); k++)
		{
			sb.append(steps.get(k));
		}
		return sb.toString();
	}

	/**
	 * The started steps, each fading from colour {@code from} to {@code to} over {@code fadeMs}
	 * after it appears. Uses only the {@code <col>} tag the game's own dialogue already uses.
	 */
	String inked(long elapsedMs, int delayMs, int fadeMs, int from, int to)
	{
		StringBuilder sb = new StringBuilder();
		int started = startedBy(elapsedMs, delayMs);
		for (int k = 0; k < started; k++)
		{
			double a = (elapsedMs - startMs(k, delayMs)) / (double) Math.max(1, fadeMs);
			if (a >= 1)
			{
				sb.append(steps.get(k));
			}
			else
			{
				sb.append(String.format("<col=%06x>", blend(from, to, a) & 0xffffff))
					.append(steps.get(k))
					.append("</col>");
			}
		}
		return sb.toString();
	}

	/** When the last step is fully inked. */
	long inkedBy(int delayMs, int fadeMs)
	{
		return steps.isEmpty() ? 0 : startMs(steps.size() - 1, delayMs) + fadeMs;
	}

	/** Linear blend of two 0xRRGGBB colours; {@code a} = 0 is {@code from}, 1 is {@code to}. */
	static int blend(int from, int to, double a)
	{
		a = Math.max(0, Math.min(1, a));
		int r = (int) Math.round(((from >> 16) & 0xff) * (1 - a) + ((to >> 16) & 0xff) * a);
		int g = (int) Math.round(((from >> 8) & 0xff) * (1 - a) + ((to >> 8) & 0xff) * a);
		int b = (int) Math.round((from & 0xff) * (1 - a) + (to & 0xff) * a);
		return (r << 16) | (g << 8) | b;
	}
}

package com.quoth;

public enum RevealMode
{
	WORD,
	LETTER,
	/** Word by word, each word fading in over the ones before it. */
	FADE;

	// One Pace setting drives every mode. At the default 130 ms per word these give 70 ms per
	// letter and a 390 ms fade, the values picked by ear when each had its own setting.
	static final double LETTER_RATIO = 0.54;
	static final int FADE_WORDS = 3;

	/** Milliseconds between steps in this mode, for a pace in milliseconds per word. */
	int delay(int paceMs)
	{
		return this == LETTER ? Math.max(10, (int) Math.round(paceMs * LETTER_RATIO)) : Math.max(10, paceMs);
	}

	/** How long a word takes to fade in, for a pace in milliseconds per word. */
	static int fadeLength(int paceMs)
	{
		return Math.max(10, paceMs) * FADE_WORDS;
	}
}

package com.quoth;

import java.util.Locale;

/** Gives every speaker a voice of their own: a pitch offset that is stable for their name. */
final class Speaker
{
	static final int SPREAD = 4;
	/** How far a species word moves a voice, in semitones. */
	static final int SPECIES_SHIFT = 5;
	/** The per-name wobble left on top of a species shift, so two goblins still differ. */
	static final int SPECIES_SPREAD = 2;

	private static final String[] GRUFF = {
		"barbarian", "ogre", "ogress", "dwarf", "dwarven", "troll", "giant", "goblin"
	};
	private static final String[] SMALL = {
		"gnome", "fairy", "child", "boy", "girl"
	};

	private Speaker()
	{
	}

	/**
	 * Semitones for an NPC name: a species shift if the name has one, plus a small per-name
	 * wobble; otherwise within [-SPREAD, SPREAD]. 0 for no name (the player, message boxes).
	 */
	static int pitchFor(String name)
	{
		if (name == null)
		{
			return 0;
		}
		String clean = name.replaceAll("<[^>]*>", "").trim().toLowerCase(Locale.ROOT);
		if (clean.isEmpty())
		{
			return 0;
		}
		int species = speciesShift(clean);
		if (species != 0)
		{
			return species + Math.floorMod(clean.hashCode(), 2 * SPECIES_SPREAD + 1) - SPECIES_SPREAD;
		}
		return Math.floorMod(clean.hashCode(), 2 * SPREAD + 1) - SPREAD;
	}

	/** -SPECIES_SHIFT for big, gruff creatures, +SPECIES_SHIFT for small ones, else 0. */
	static int speciesShift(String lowerName)
	{
		for (String word : lowerName.split("[^a-z]+"))
		{
			for (String g : GRUFF)
			{
				if (word.equals(g) || word.equals(g + "s"))
				{
					return -SPECIES_SHIFT;
				}
			}
			for (String s : SMALL)
			{
				if (word.equals(s) || word.equals(s + "s"))
				{
					return SPECIES_SHIFT;
				}
			}
		}
		return 0;
	}

	/**
	 * The colour a word starts from when it fades in: the text colour pulled most of the way
	 * toward the parchment behind dark text, or toward black behind light text.
	 */
	static int faintOf(int textColor)
	{
		int r = (textColor >> 16) & 0xff;
		int g = (textColor >> 8) & 0xff;
		int b = textColor & 0xff;
		double luma = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
		int ground = luma < 0.5 ? PARCHMENT : 0x000000;
		return Reveal.blend(textColor, ground, 0.8);
	}

	// Approximate mid-tone of the dialogue box's parchment.
	private static final int PARCHMENT = 0xc8b28a;
}

package com.quoth;

import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;

/**
 * Minimal PCM WAV reading and writing, so Quoth can decode, pitch and trim its blips in memory
 * and hand RuneLite's AudioPlayer a finished file. Everything inside Quoth is 16-bit mono at
 * {@link #RATE}.
 */
final class Wav
{
	static final int RATE = 44100;

	private static final int FORMAT_PCM = 1;
	private static final int FORMAT_EXTENSIBLE = 0xFFFE;

	private Wav()
	{
	}

	/**
	 * Decodes a PCM WAV (8, 16 or 24-bit, any channel count, any rate) to 16-bit little-endian
	 * mono at {@link #RATE}.
	 */
	static byte[] decode(byte[] wav) throws IOException
	{
		ByteBuffer b = ByteBuffer.wrap(wav).order(ByteOrder.LITTLE_ENDIAN);
		if (wav.length < 12 || b.getInt(0) != 0x46464952 || b.getInt(8) != 0x45564157) // "RIFF", "WAVE"
		{
			throw new IOException("not a WAV file");
		}
		int format = -1;
		int channels = 0;
		int rate = 0;
		int bits = 0;
		int dataStart = -1;
		int dataLength = 0;
		int pos = 12;
		while (pos + 8 <= wav.length)
		{
			int id = b.getInt(pos);
			int size = b.getInt(pos + 4);
			int body = pos + 8;
			if (size < 0 || body + size > wav.length)
			{
				size = wav.length - body; // tolerate a truncated last chunk
			}
			if (id == 0x20746d66 && size >= 16) // "fmt "
			{
				format = b.getShort(body) & 0xffff;
				channels = b.getShort(body + 2) & 0xffff;
				rate = b.getInt(body + 4);
				bits = b.getShort(body + 14) & 0xffff;
				if (format == FORMAT_EXTENSIBLE && size >= 26)
				{
					format = b.getShort(body + 24) & 0xffff; // sub-format GUID starts with the format code
				}
			}
			else if (id == 0x61746164) // "data"
			{
				dataStart = body;
				dataLength = size;
			}
			pos = body + size + (size & 1); // chunks are padded to even length
		}
		if (format != FORMAT_PCM || dataStart < 0 || channels < 1 || rate <= 0
			|| (bits != 8 && bits != 16 && bits != 24))
		{
			throw new IOException("unsupported WAV: format=" + format + " bits=" + bits + " channels=" + channels);
		}

		int bytesPer = bits / 8;
		int frames = dataLength / (bytesPer * channels);
		byte[] mono = new byte[frames * 2];
		for (int f = 0; f < frames; f++)
		{
			int sum = 0;
			for (int c = 0; c < channels; c++)
			{
				int at = dataStart + (f * channels + c) * bytesPer;
				int s;
				if (bits == 8)
				{
					s = ((wav[at] & 0xff) - 128) << 8; // 8-bit WAV is unsigned
				}
				else if (bits == 16)
				{
					s = (short) ((wav[at] & 0xff) | (wav[at + 1] << 8));
				}
				else
				{
					s = ((wav[at] & 0xff) | ((wav[at + 1] & 0xff) << 8) | (wav[at + 2] << 16)) >> 8;
				}
				sum += s;
			}
			int s = Math.round(sum / (float) channels);
			mono[2 * f] = (byte) s;
			mono[2 * f + 1] = (byte) (s >> 8);
		}
		return rate == RATE ? mono : Resample.shift(mono, rate / (double) RATE);
	}

	/** Wraps 16-bit little-endian mono PCM at {@link #RATE} in a WAV header. */
	static byte[] encode(byte[] pcm)
	{
		ByteBuffer b = ByteBuffer.allocate(44 + pcm.length).order(ByteOrder.LITTLE_ENDIAN);
		b.putInt(0x46464952).putInt(36 + pcm.length).putInt(0x45564157); // RIFF size WAVE
		b.putInt(0x20746d66).putInt(16).putShort((short) FORMAT_PCM).putShort((short) 1) // fmt, mono
			.putInt(RATE).putInt(RATE * 2).putShort((short) 2).putShort((short) 16);
		b.putInt(0x61746164).putInt(pcm.length).put(pcm); // data
		return b.array();
	}
}

package com.quoth;

import static org.junit.Assert.assertEquals;
