package com.quoth;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class FadeTest
{
	private static final String LINE = "Hello <col=ff0000>brave</col> adventurer!<br>Welcome.";
	private final Reveal r = Reveal.of(LINE, RevealMode.FADE);

	@Test
	public void finishesAsExactlyTheGameText()
	{
		assertEquals(LINE, r.inked(r.inkedBy(100, 300), 100, 300, 0xaaaaaa, 0x000000));
	}

	@Test
	public void newWordStartsFaintAndDarkens()
	{
		String first = r.inked(0, 100, 300, 0xc8b28a, 0x000000);
		assertTrue(first, first.startsWith("<col=c8b28a>Hello</col>"));
		String later = r.inked(150, 100, 300, 0xc8b28a, 0x000000);
		assertTrue(later, later.startsWith("<col=645945>Hello</col>")); // halfway
	}

	@Test
	public void unstartedWordsAreAbsent()
	{
		String first = r.inked(0, 100, 300, 0xaaaaaa, 0x000000);
		assertTrue(first, !first.contains("brave") && !first.contains("Welcome"));
	}

	@Test
	public void faintIsTowardParchmentForDarkTextAndBlackForLight()
	{
		assertEquals(Reveal.blend(0x000000, 0xc8b28a, 0.8), Speaker.faintOf(0x000000));
		assertEquals(Reveal.blend(0xffffff, 0x000000, 0.8), Speaker.faintOf(0xffffff));
	}
}

package com.quoth;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class MoodTest
{
	@Test
	public void questionAndExclamationMarkTheirWord()
	{
		Reveal r = Reveal.of("Did you bring them? Hurry! \"Now?!\" ok", RevealMode.WORD);
		// Did you bring them? Hurry! "Now?!" ok
		assertEquals(0, r.mood(0));
		assertEquals(Reveal.MOOD_QUESTION, r.mood(3));
		assertEquals(Reveal.MOOD_EXCLAIM, r.mood(4));
		assertEquals(Reveal.MOOD_QUESTION | Reveal.MOOD_EXCLAIM, r.mood(5));
		assertEquals(0, r.mood(6));
		assertEquals(0, r.mood(99));
	}

	@Test
	public void letterModeMarksThePunctuationItself()
	{
		Reveal r = Reveal.of("Hi?", RevealMode.LETTER);
		assertEquals(0, r.mood(1));
		assertEquals(Reveal.MOOD_QUESTION, r.mood(2));
	}

	@Test
	public void colourTagsDoNotHideTheMark()
	{
		Reveal r = Reveal.of("<col=ff0000>Run!</col>", RevealMode.WORD);
		assertEquals(Reveal.MOOD_EXCLAIM, r.mood(0));
	}

	@Test
	public void bigFolkSoundLowerAndSmallFolkHigher()
	{
		for (String n : new String[]{"Barbarian guard", "Ogre trader", "Dwarven Boatman", "Goblin", "Hill Giant", "Ogress Warrior"})
		{
			int p = Speaker.pitchFor(n);
			assertTrue(n + " -> " + p, p <= -Speaker.SPECIES_SHIFT + Speaker.SPECIES_SPREAD);
		}
		for (String n : new String[]{"Fairy Nuff", "Fairy Godfather", "Gnome banker", "Gnome trainer", "Gnome Coach"})
		{
			int p = Speaker.pitchFor(n);
			assertTrue(n + " -> " + p, p >= Speaker.SPECIES_SHIFT - Speaker.SPECIES_SPREAD);
		}
	}

	@Test
	public void talkableNpcsAreRecognisedBySpeciesNotByNameLuck()
	{
		// Checked against the OSRS Wiki: each has a Talk-to option.
		for (String n : new String[]{"barbarian guard", "ogre trader", "dwarven boatman"})
		{
			assertEquals(n, -Speaker.SPECIES_SHIFT, Speaker.speciesShift(n));
		}
		for (String n : new String[]{"fairy nuff", "fairy godfather", "gnome banker", "gnome trainer", "gnome coach"})
		{
			assertEquals(n, Speaker.SPECIES_SHIFT, Speaker.speciesShift(n));
		}
	}

	@Test
	public void speciesMatchesWholeWordsOnly()
	{
		// "Impling" and "Bearded" must not match "imp" or "bear".
		assertEquals(0, Speaker.speciesShift("impling"));
		assertEquals(0, Speaker.speciesShift("bearded man"));
		assertEquals(0, Speaker.speciesShift("cook"));
	}
}

