package com.quoth;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

import org.junit.Test;

public class ResampleTest
{
	private static byte[] ramp(int frames)
	{
		byte[] pcm = new byte[frames * 2];
		for (int i = 0; i < frames; i++)
		{
			int s = i * 100 - 5000;
			pcm[2 * i] = (byte) s;
			pcm[2 * i + 1] = (byte) (s >> 8);
		}
		return pcm;
	}

	@Test
	public void ratioIsEqualTempered()
	{
		assertEquals(2.0, Resample.ratio(12, 0), 1e-9);
		assertEquals(0.5, Resample.ratio(-12, 0), 1e-9);
		assertEquals(Resample.ratio(1, 0), Resample.ratio(0, 100), 1e-9);
	}

	@Test
	public void unityRatioIsLossless()
	{
		byte[] pcm = ramp(100);
		assertArrayEquals(pcm, Resample.shift(pcm, 1.0));
	}

	@Test
	public void octaveUpHalvesLengthAndKeepsEverySecondSample()
	{
		byte[] pcm = ramp(100);
		byte[] up = Resample.shift(pcm, 2.0);
		assertEquals(pcm.length / 2, up.length);
		assertEquals(pcm[4], up[2]);
		assertEquals(pcm[5], up[3]);
	}

	@Test
	public void negativeSamplesSurviveTheRoundTrip()
	{
		byte[] pcm = ramp(10); // starts at -5000
		byte[] out = Resample.shift(pcm, 1.0);
		assertEquals(-5000, (short) ((out[0] & 0xff) | (out[1] << 8)));
	}

	@Test
	public void trimCutsToLengthAndEndsInSilence()
	{
		byte[] pcm = ramp(100);
		byte[] cut = Resample.trim(pcm, 40, 10);
		assertEquals(80, cut.length);
		assertEquals(0, (short) ((cut[78] & 0xff) | (cut[79] << 8)));
		assertEquals(pcm[0], cut[0]);
		assertEquals(pcm[59], cut[59]); // untouched before the fade
	}

	@Test
	public void trimLeavesShortOrUnboundedInputAlone()
	{
		byte[] pcm = ramp(30);
		assertArrayEquals(pcm, Resample.trim(pcm, 40, 10));
		assertArrayEquals(pcm, Resample.trim(pcm, 0, 10));
	}

}

package com.quoth;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

import org.junit.Test;

public class RevealTest
{
	private static final String LINE = "Hello <col=ff0000>brave</col> adventurer!<br>Welcome.";

	@Test
	public void wordStepsEndOnTheFullText()
	{
		Reveal r = Reveal.of(LINE, RevealMode.WORD);
		assertEquals(4, r.size());
		assertEquals("Hello", r.prefix(1));
		assertEquals("Hello <col=ff0000>brave", r.prefix(2));
		assertEquals(LINE, r.prefix(r.size()));
	}

	@Test
	public void noPrefixEverSplitsATag()
	{
		for (RevealMode mode : RevealMode.values())
		{
			Reveal r = Reveal.of(LINE, mode);
			for (int n = 0; n <= r.size(); n++)
			{
				String p = r.prefix(n);
				assertFalse(mode + " step " + n + ": " + p, p.lastIndexOf('<') > p.lastIndexOf('>'));
			}
			assertEquals(LINE, r.prefix(r.size()));
		}
	}

	@Test
	public void letterModeRevealsOneCharacterPerStep()
	{
		Reveal r = Reveal.of("Hi there", RevealMode.LETTER);
		assertEquals(7, r.size());
		assertEquals("Hi t", r.prefix(3));
	}

	@Test
	public void trailingMarkupAndEmptyTextSurvive()
	{
		assertEquals("Bye.</col>", Reveal.of("Bye.</col>", RevealMode.WORD).prefix(1));
		assertEquals(0, Reveal.of("", RevealMode.WORD).size());
	}
}

package com.quoth;

import static org.junit.Assert.assertEquals;

import org.junit.Test;

public class RhythmTest
{
	@Test
	public void wordsPauseAtCommasStopsAndEllipses()
	{
		// Erm... | Sorry, | I | don't.
		Reveal r = Reveal.of("Erm... Sorry, I don't.", RevealMode.WORD);
		assertEquals(0, r.startMs(0, 100));
		assertEquals((1 + Reveal.PAUSE_ELLIPSIS) * 100, r.startMs(1, 100));
		assertEquals(r.startMs(1, 100) + (1 + Reveal.PAUSE_COMMA) * 100, r.startMs(2, 100));
		assertEquals(r.startMs(2, 100) + 100, r.startMs(3, 100));
	}

	@Test
	public void lettersPauseOnceAtTheEndOfAnEllipsis()
	{
		Reveal r = Reveal.of("Hm... ok", RevealMode.LETTER); // H m . . . o k
		assertEquals(100, r.startMs(1, 100)); // m
		assertEquals(200, r.startMs(2, 100)); // first dot, no pause after m
		assertEquals(300, r.startMs(3, 100)); // dots run on
		assertEquals(400, r.startMs(4, 100));
		assertEquals(400 + (1 + Reveal.PAUSE_ELLIPSIS) * 100, r.startMs(5, 100)); // o waits
	}

	@Test
	public void punctuationRunsAndClosingQuotesPauseOnce()
	{
		assertEquals(0, Reveal.pauseAfter("What?", '!'));
		assertEquals(Reveal.PAUSE_STOP, Reveal.pauseAfter("What?!", ' '));
		assertEquals(Reveal.PAUSE_STOP, Reveal.pauseAfter("\"Go.\"", 'H'));
		assertEquals(0, Reveal.pauseAfter("plain", 'x'));
	}

	@Test
	public void startedByFollowsTheSchedule()
	{
		Reveal r = Reveal.of("One. Two", RevealMode.WORD);
		assertEquals(1, r.startedBy(0, 100));
		assertEquals(1, r.startedBy(399, 100));
		assertEquals(2, r.startedBy(400, 100));
	}

	@Test
	public void speakersGetStableDistinctPitchesInRange()
	{
		assertEquals(Speaker.pitchFor("Cook"), Speaker.pitchFor("<col=ff0000>cook</col>"));
		assertEquals(0, Speaker.pitchFor(null));
		assertEquals(0, Speaker.pitchFor(""));
		java.util.Set<Integer> seen = new java.util.HashSet<>();
		for (String n : new String[]{"Cook", "Hans", "Duke Horacio", "Bob", "Wise Old Man", "Gertrude", "Zaff"})
		{
			int p = Speaker.pitchFor(n);
			assertEquals(true, p >= -Speaker.SPREAD && p <= Speaker.SPREAD);
			seen.add(p);
		}
		assertEquals(true, seen.size() > 2);
	}
}

package com.quoth;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.io.File;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.file.Files;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Filepath;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class SampleFolderTest
{
	@Rule
	public TemporaryFolder tmp = new TemporaryFolder();

	/** Writes a PCM WAV by hand, so the tests share no code with the decoder they check. */
	static byte[] wav(int rate, int bits, int channels, int frames, int value)
	{
		int bytesPer = bits / 8;
		int dataLen = frames * channels * bytesPer;
		ByteBuffer b = ByteBuffer.allocate(44 + dataLen).order(ByteOrder.LITTLE_ENDIAN);
		b.put("RIFF".getBytes()).putInt(36 + dataLen).put("WAVE".getBytes());
		b.put("fmt ".getBytes()).putInt(16).putShort((short) 1).putShort((short) channels)
			.putInt(rate).putInt(rate * channels * bytesPer).putShort((short) (channels * bytesPer)).putShort((short) bits);
		b.put("data".getBytes()).putInt(dataLen);
		for (int i = 0; i < frames * channels; i++)
		{
			if (bits == 8)
			{
				b.put((byte) ((value >> 8) + 128));
			}
			else if (bits == 16)
			{
				b.putShort((short) value);
			}
			else
			{
				int v = value << 8;
				b.put((byte) v).put((byte) (v >> 8)).put((byte) (v >> 16));
			}
		}
		return b.array();
	}

	private static short first(byte[] pcm)
	{
		return (short) ((pcm[0] & 0xff) | (pcm[1] << 8));
	}

	@Test
	public void sixteenBitMonoAtFullRatePassesThrough() throws Exception
	{
		byte[] pcm = Wav.decode(wav(44100, 16, 1, 441, -1234));
		assertEquals(441, pcm.length / 2);
		assertEquals(-1234, first(pcm));
	}

	@Test
	public void stereo48kDecodesToMono44k() throws Exception
	{
		assertEquals(4410, Wav.decode(wav(48000, 16, 2, 4800, 1000)).length / 2, 2); // 100 ms
	}

	@Test
	public void eightBitAndTwentyFourBitKeepTheirLevel() throws Exception
	{
		assertEquals(4410, Wav.decode(wav(22050, 8, 1, 2205, 0)).length / 2, 2);
		assertEquals(-12800, first(Wav.decode(wav(44100, 8, 1, 10, -12800))));
		assertEquals(20000, first(Wav.decode(wav(44100, 24, 1, 10, 20000))));
	}

	@Test
	public void encodeThenDecodeIsLossless() throws Exception
	{
		byte[] pcm = Wav.decode(wav(44100, 16, 1, 100, 777));
		org.junit.Assert.assertArrayEquals(pcm, Wav.decode(Wav.encode(pcm)));
	}

	@Test(expected = java.io.IOException.class)
	public void nonWavIsRefused() throws Exception
	{
		Wav.decode("not audio at all".getBytes());
	}

	@Test
	public void folderLoadsWavsAndSkipsEverythingElse() throws Exception
	{
		File dir = tmp.newFolder("quoth");
		Files.write(new File(dir, "a.wav").toPath(), wav(44100, 16, 1, 441, 1));
		Files.write(new File(dir, "b.WAV").toPath(), wav(48000, 16, 2, 480, 1));
		Files.write(new File(dir, "notes.txt").toPath(), "hi".getBytes());
		Files.write(new File(dir, "broken.wav").toPath(), "not audio".getBytes());
		assertEquals(2, new BlipPlayer(folder(dir), null).refreshUser());
	}

	@Test
	public void missingFolderLoadsNothingAndIsNotCreated()
	{
		File absent = new File(tmp.getRoot(), "absent");
		assertEquals(0, new BlipPlayer(folder(absent), null).refreshUser());
		assertFalse(absent.exists());
	}

	@Test
	public void noFolderFromTheClientLoadsNothing()
	{
		BlipPlayer p = new BlipPlayer(null, null);
		assertEquals(0, p.refreshUser());
		assertFalse(p.hasUser("2266"));
	}

	/** Without internalName the client throws instead of giving a folder. */
	@Test
	public void descriptorNamesTheHubPluginAndAnAcceptedLegacyFolder()
	{
		PluginDescriptor d = QuothPlugin.class.getAnnotation(PluginDescriptor.class);
		assertEquals("quoth", d.internalName());
		Filepath.Unchecked.getLegacyPluginDirectory(tmp.getRoot().toPath(), d.legacyDataDirectory());
	}

	/** The client hands plugins a Filepath; tests stand one up over a temp folder. */
	private static Filepath folder(File dir)
	{
		return Filepath.Unchecked.getRooted(dir.toPath());
	}

	@Test
	public void soundIdsFindTheirFileCaseInsensitively() throws Exception
	{
		File dir = tmp.newFolder("ids");
		Files.write(new File(dir, "2266.WAV").toPath(), wav(22050, 16, 1, 441, 1));
		BlipPlayer p = new BlipPlayer(folder(dir), null);
		assertTrue(p.hasUser("2266"));
		assertFalse(p.hasUser("9999"));
	}

	@Test
	public void volumeMapsToGainWithFullAsUnity()
	{
		assertEquals(0f, BlipPlayer.gainDb(100), 1e-6);
		assertEquals(-6.02f, BlipPlayer.gainDb(50), 0.01);
	}
}
